import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"17、【随】 震下兑上","description":"周易尚氏学 - 17、【随】 震下兑上","frontmatter":{"title":"17、【随】 震下兑上","description":"周易尚氏学 - 17、【随】 震下兑上"},"headers":[],"relativePath":"zh/classics/shangshi/022.md","filePath":"zh/classics/shangshi/022.md"}'),h={name:"zh/classics/shangshi/022.md"};function s(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_17、【随】-震下兑上" tabindex="-1">17、【随】 震下兑上 <a class="header-anchor" href="#_17、【随】-震下兑上" aria-label="Permalink to “17、【随】 震下兑上”">​</a></h1><p>归藏曰马徒。马徒。即周礼太仆职所谓前驱。越语勾践亲为夫差前马。注前马前驱。在马前也。按震为马。互艮为徒隶。马徒皆随贵人马。前行以辟道。而兑为口。为传呼。于卦象颇合。兹周易名随。似取随时之义。震春。故曰元亨。兑秋。故曰利贞。吉春而夏可赅。言秋而科可赅。元亨利贞。即春夏秋冬。周而复始。循环不穷。故曰随。随时而动。不过不忒。故无咎。</p><p>彖曰。随。刚来而下柔。动而说。随。大亨贞无咎。而天下随时。随时之义大矣哉。</p><p>王肃本。随时。皆作随之。将卦义全失。朱于从之过矣。故夫读易以明理为先也。</p><p>象曰。泽中有雷。随。君子以晌晦入宴息。艮为君子。又止故宴息。兑为昧为晦。震往。往而遇兑。故曰晌晦。巽伏。故君子法此象。以晌晦人宴息。</p><p>初九。官有渝。贞吉。出门交有功。</p><p>官。蜀才作馆。见释文。惠栋云。官。古文馆。以穆天子传。官人陈牲为证。按作馆是也。艮为馆。下卦艮覆。故曰馆有渝。渝变也。初至四为正覆良。象覆即于覆取义。易通例也。自覆象失传。渝之古旧解皆不能说其所以然。而用覆之辞。如蒙掾（无左）如中孚之二三交。诂皆误矣。渝而得位。故贞吉。与下贞凶为对文。艮为门。初临之。而震为出。故曰出门。出门则有交接。阳遇阴则通。故有功。凡阳临重阴者无不吉。此其一也。</p><h3 id="象曰。官有偷。从正吉也。出门交有功。不失也。" tabindex="-1">象曰。官有偷。从正吉也。出门交有功。不失也。 <a class="header-anchor" href="#象曰。官有偷。从正吉也。出门交有功。不失也。" aria-label="Permalink to “象曰。官有偷。从正吉也。出门交有功。不失也。”">​</a></h3><p>失与佚通用。供逸也。震动故不佚。言不敢安逸也。此与比六二不自失。小畜九二亦不自失。皆读为佚。与吉韵。义详比九五失前禽注。</p><p>六二。系小子。失丈夫。</p><p>此爻旧解。淆乱至今者。一由卦象失传。二由同性相敌之理不明也。初震为小子。四艮为丈夫。二近初。故系小子。为六三所隔。不能承四。故失丈夫。易林家人之巽云。孩子贪饵。以伏震为孩子也。孩子即小子。是焦氏以震为小子。义即本此也。又复之剥云。夫亡从军。以剥上艮为夫。是艮为丈夫。焦氏仍本之易。盖以二人言。初生者长。后生者少。故说卦以震为长子。艮为少子。而以一人言。则初少上老。故经以震为小子。艮为丈夫。先儒不知经取象。往往与说卦不同。不敢直认。岂知象传所释至明也。</p><h3 id="象曰。系小子。弗兼与也。" tabindex="-1">象曰。系小子。弗兼与也。 <a class="header-anchor" href="#象曰。系小子。弗兼与也。" aria-label="Permalink to “象曰。系小子。弗兼与也。”">​</a></h3><p>二居初四之间。近初远四。故曰弗兼与。虞翻谓二应五。以五为小子。五为少女。焉能为小子。失之远矣。</p><p>六三。系丈夫。失小子。随有求。句得。句利居贞。</p><p>三近四承阳。故上系文夫。为二所阻。故下失小子。象谓志合下。是明以震为小于。艮为丈夫也。随有求句。与下随有获对文。艮为求。阴承阳故有得。巽为利。咸六二云。居吉。兹云利居贞。似亦以动为戒。盖上无应。静而承阳则吉。动则不利。旧解谓之正应上。于居义相背。非也。</p><h3 id="象曰。系丈夫。志合下也。" tabindex="-1">象曰。系丈夫。志合下也。 <a class="header-anchor" href="#象曰。系丈夫。志合下也。" aria-label="Permalink to “象曰。系丈夫。志合下也。”">​</a></h3><p>下谓初。轻以艮为丈夫。以震为小子。可谓明白矣。</p><p>九四。随有获。贞凶。有孚。在道以明。何咎。</p><p>下乘重阴得民。故有获。不当位。前遇敌。故贞凶。然下孚于众。光明正大。遵循正道。亦无咎也。艮为道。为光明。虞氏命三四全变成离。取明象。迂曲失经旨。大畜彖传曰。刚健笃实辉光。刚健谓乾。辉光谓艮。是艮为光明。易有明文。</p><h3 id="象曰。随有获。其义凶也。有孚在道。明功也。其义凶者。" tabindex="-1">象曰。随有获。其义凶也。有孚在道。明功也。其义凶者。 <a class="header-anchor" href="#象曰。随有获。其义凶也。有孚在道。明功也。其义凶者。" aria-label="Permalink to “象曰。随有获。其义凶也。有孚在道。明功也。其义凶者。”">​</a></h3><p>谓四本不凶。而凶者以不当位也。大畜颐上九皆下孚于阴而吉。</p><p>九五。孚于嘉。吉。</p><p>易林每以震为嘉。盖本此也。嘉指二。五孚于二。二震体。故曰孚于嘉。</p><h3 id="象曰。孚于嘉。位正中也。" tabindex="-1">象曰。孚于嘉。位正中也。 <a class="header-anchor" href="#象曰。孚于嘉。位正中也。" aria-label="Permalink to “象曰。孚于嘉。位正中也。”">​</a></h3><p>二五皆当位。故曰正中。</p><p>上六。拘系之。乃从维之。王用亨于西山。</p><p>伏艮为拘为山。兑西故曰西山，兑口故曰亨。王渭五。三至上正反巽。巽为绳。故曰系。曰维。虞翻曰。两系称维。正反两类诗所谓絷之维之也。卦以随为义。六穷于上。五恐其去。拘系之。从维之。或即其隐居之处而宴享之。言六无所随。而五必随之也。西溪易说云。先儒说易。遇西山西邻。皆曰文王事也。可谓大谬。</p><h3 id="象曰。拘系之。上穷也。" tabindex="-1">象曰。拘系之。上穷也。 <a class="header-anchor" href="#象曰。拘系之。上穷也。" aria-label="Permalink to “象曰。拘系之。上穷也。”">​</a></h3><p>穷尽也。</p>',29)])])}const m=e(h,[["render",s]]);export{_ as __pageData,m as default};
